import type { IconName } from '@/components/ui/Icon';
import type {
  AccessRequest,
  AppNotification,
  AuthAttempts,
  Comment,
  Hire,
  HireTask,
  NotificationType,
  Person,
  PrivacyRequest,
} from '@/types/domain';
import { addDays, DEMO_TODAY } from './dates';
import { CHECKIN_OFFSETS, isPastDue, taskStatus } from './journey';

/**
 * Notification engine (F7). Notifications are generated by system events: the seed derives the
 * ones that the demo data implies at DEMO_TODAY, and the data store adds new ones when something
 * happens during the session (a task unblocks another, a self-review is sent, a request arrives).
 * Texts are never stored: each notification keeps its type and parameters and the interface
 * translates them, so they read well in Spanish and English (D-105).
 */

export type NotificationCategory = 'tasks' | 'checkins' | 'people' | 'access';

interface TypeMeta {
  category: NotificationCategory;
  icon: IconName;
  /** Tone of the icon tile: state colors only for states (2.1.1). */
  tone: 'primary' | 'tertiary' | 'warning' | 'error' | 'success' | 'info';
  /** Also sent by email (simulated) by default; preferences (F17) can change it. */
  email: boolean;
}

export const NOTIFICATION_TYPES: Record<NotificationType, TypeMeta> = {
  'task.due_soon': { category: 'tasks', icon: 'schedule', tone: 'warning', email: true },
  'task.overdue': { category: 'tasks', icon: 'error', tone: 'error', email: true },
  'task.unblocked': { category: 'tasks', icon: 'lock_open', tone: 'success', email: false },
  'task.journey_overdue': { category: 'tasks', icon: 'error', tone: 'error', email: true },
  'checkin.self_review_pending': { category: 'checkins', icon: 'event', tone: 'tertiary', email: true },
  'checkin.self_review_done': { category: 'checkins', icon: 'fact_check', tone: 'primary', email: true },
  'checkin.manager_due': { category: 'checkins', icon: 'event', tone: 'tertiary', email: true },
  'checkin.completed': { category: 'checkins', icon: 'check_circle', tone: 'success', email: true },
  'checkin.escalated': { category: 'checkins', icon: 'warning', tone: 'error', email: true },
  'journey.delayed': { category: 'people', icon: 'warning', tone: 'warning', email: false },
  'hire.assigned': { category: 'people', icon: 'person_add', tone: 'primary', email: true },
  'hire.starting': { category: 'people', icon: 'event', tone: 'info', email: false },
  'access_request.new': { category: 'access', icon: 'support_agent', tone: 'info', email: true },
  'account.locked': { category: 'access', icon: 'lock', tone: 'error', email: false },
  'access_request.resolved': { category: 'access', icon: 'check_circle', tone: 'success', email: true },
  'access_request.rejected': { category: 'access', icon: 'cancel', tone: 'error', email: true },
  'comment.new': { category: 'tasks', icon: 'chat', tone: 'primary', email: false },
  'comment.mention': { category: 'tasks', icon: 'alternate_email', tone: 'tertiary', email: true },
  'privacy_request.new': { category: 'people', icon: 'policy', tone: 'info', email: true },
  'privacy_request.answered': { category: 'people', icon: 'policy', tone: 'success', email: true },
};

export const NOTIFICATION_CATEGORIES: NotificationCategory[] = ['tasks', 'checkins', 'people', 'access'];

/** Days before the due date when a task is announced as "por vencer" (CLAUDE.md F7). */
export const DUE_SOON_DAYS = 2;
/** Notifications older than this many days are seeded as already read. */
const SEED_READ_AFTER_DAYS = 3;
/** How far back the seed recreates past reminders ("por vencer"), so each inbox has a history. */
const SEED_HISTORY_DAYS = 45;
/** The newest ones of each person stay unread, so every inbox opens with something new. */
const SEED_UNREAD_NEWEST = 3;

type Draft = Omit<AppNotification, 'id' | 'channels' | 'readAt'>;

let counter = 0;
function nextId(): string {
  counter += 1;
  return `nt-${Date.now().toString(36)}-${counter}`;
}

/** Completes a draft with its id and channels. */
export function makeNotification(draft: Draft, id = nextId()): AppNotification {
  return { ...draft, id, channels: NOTIFICATION_TYPES[draft.type].email ? ['app', 'email'] : ['app'] };
}

/** Who acts on a task: the hire, the manager, or HR for buddy, IT and Facilities tasks (D-09). */
function taskRecipient(hire: Hire, task: Pick<HireTask, 'owner'>): string {
  if (task.owner === 'hire') return hire.personId;
  if (task.owner === 'manager') return hire.managerId;
  return hire.hrId;
}

/** Link to the task for whoever receives it, in their own workspace. */
function taskLink(hire: Hire, task: HireTask, recipientId: string): string {
  if (recipientId === hire.personId) return `/me/tasks/${task.id}`;
  if (recipientId === hire.managerId) return `/manager/hires/${hire.id}`;
  return `/admin/hires/${hire.id}`;
}

// 12:00 UTC is 09:00 in Buenos Aires, the demo time zone (F17).
const at = (date: string, time = '12:00:00') => `${date}T${time}.000Z`;

// ---------- Events during the session ----------

/** A task was completed: the tasks it unblocked are announced to whoever has to do them. */
export function onTaskCompleted(hire: Hire, unlockedIds: string[], when: string): AppNotification[] {
  return unlockedIds
    .map((id) => hire.tasks.find((t) => t.id === id))
    .filter((t): t is HireTask => Boolean(t))
    .map((task) => {
      const recipientId = taskRecipient(hire, task);
      return makeNotification({
        recipientId,
        createdAt: when,
        type: 'task.unblocked',
        params: { task: task.title },
        link: taskLink(hire, task, recipientId),
      });
    });
}

/** The hire sent their self-review: the manager is told so the meeting can happen. */
export function onSelfReview(hire: Hire, person: Person | undefined, stage: keyof typeof CHECKIN_OFFSETS, when: string) {
  return [
    makeNotification({
      recipientId: hire.managerId,
      createdAt: when,
      type: 'checkin.self_review_done',
      params: { person: person?.name ?? '', days: String(CHECKIN_OFFSETS[stage]) },
      link: `/manager/hires/${hire.id}/checkin/${stage}`,
    }),
  ];
}

/** The manager completed a check-in: the hire is told and, if it was escalated, HR too. */
export function onCheckinCompleted(
  hire: Hire,
  person: Person | undefined,
  stage: keyof typeof CHECKIN_OFFSETS,
  escalated: boolean,
  when: string,
): AppNotification[] {
  const days = String(CHECKIN_OFFSETS[stage]);
  const list = [
    makeNotification({
      recipientId: hire.personId,
      createdAt: when,
      type: 'checkin.completed',
      params: { days },
      link: '/me',
    }),
  ];
  if (escalated) {
    list.push(
      makeNotification({
        recipientId: hire.hrId,
        createdAt: when,
        type: 'checkin.escalated',
        params: { person: person?.name ?? '', days },
        link: `/admin/hires/${hire.id}`,
      }),
    );
  }
  return list;
}

/** A new access request reaches every IT admin. */
export function onAccessRequest(request: AccessRequest, people: Person[]): AppNotification[] {
  const person = people.find((p) => p.id === request.personId);
  return people
    .filter((p) => p.role === 'it_admin')
    .map((it) =>
      makeNotification({
        recipientId: it.id,
        createdAt: request.createdAt,
        type: 'access_request.new',
        params: { request: request.id, person: person?.name ?? request.email },
        link: `/it/requests/${request.id}`,
      }),
    );
}

/** IT resolved or rejected a request: the person is told (only if the account is known). */
export function onAccessRequestClosed(request: AccessRequest, resolved: boolean, when: string): AppNotification[] {
  if (!request.personId) return [];
  return [
    makeNotification({
      recipientId: request.personId,
      createdAt: when,
      type: resolved ? 'access_request.resolved' : 'access_request.rejected',
      params: { request: request.id },
      link: '/account/security',
    }),
  ];
}

/** HR added a hire: the manager learns that someone joins the team. */
export function onHireCreated(hire: Hire, person: Person, when: string): AppNotification[] {
  return [
    makeNotification({
      recipientId: hire.managerId,
      createdAt: when,
      type: 'hire.assigned',
      params: { person: person.name, date: hire.startDate },
      link: `/manager/hires/${hire.id}`,
    }),
  ];
}

/**
 * A comment was posted (F9): the people mentioned get "Te mencionaron"; the rest of the thread
 * (the hire and whoever commented before) gets "Comentario nuevo". Never the author.
 */
export function onComment(
  hire: Hire,
  task: HireTask,
  comment: { authorId: string; mentions: string[]; createdAt: string },
  earlierAuthors: string[],
  authorName: string,
): AppNotification[] {
  const mentioned = new Set(comment.mentions.filter((id) => id !== comment.authorId));
  const thread = new Set([hire.personId, ...earlierAuthors].filter((id) => id !== comment.authorId && !mentioned.has(id)));
  const make = (recipientId: string, type: 'comment.new' | 'comment.mention') =>
    makeNotification({
      recipientId,
      createdAt: comment.createdAt,
      type,
      params: { person: authorName, task: task.title },
      link: commentLink(hire, task, recipientId),
    });
  return [...[...mentioned].map((id) => make(id, 'comment.mention')), ...[...thread].map((id) => make(id, 'comment.new'))];
}

/** Where a comment is read: the task detail for the hire, the thread in the record for the others. */
export function commentLink(hire: Hire, task: Pick<HireTask, 'id'>, recipientId: string): string {
  if (recipientId === hire.personId) return `/me/tasks/${task.id}#comments`;
  if (recipientId === hire.managerId) return `/manager/hires/${hire.id}?comments=${task.id}`;
  return `/admin/hires/${hire.id}?comments=${task.id}`;
}

/** F10: a new request about personal data reaches every HR admin; the answer reaches the person. */
export function onPrivacyRequest(request: PrivacyRequest, people: Person[], personName: string): AppNotification[] {
  return people
    .filter((p) => p.role === 'admin')
    .map((hr) =>
      makeNotification({
        recipientId: hr.id,
        createdAt: request.createdAt,
        type: 'privacy_request.new',
        params: { request: request.id, person: personName, date: request.dueAt },
        link: `/admin/privacy-requests?request=${request.id}`,
      }),
    );
}

export function onPrivacyAnswered(request: PrivacyRequest, when: string): AppNotification[] {
  return [
    makeNotification({
      recipientId: request.personId,
      createdAt: when,
      type: 'privacy_request.answered',
      params: { request: request.id },
      link: '/account/privacy',
    }),
  ];
}

// ---------- Seed ----------

/**
 * Notifications implied by the demo data at DEMO_TODAY (CLAUDE.md 7, phase B seed), generated
 * with the same rules as the events above so seed and runtime never disagree. Those older
 * than two days are already read. Ids are stable, so the seed is the same on every load.
 */
export function buildSeedNotifications(
  hires: Hire[],
  people: Person[],
  accessRequests: AccessRequest[],
  authAttempts: AuthAttempts[],
  comments: Comment[] = [],
  today = DEMO_TODAY,
): AppNotification[] {
  const nameOf = (id: string) => people.find((p) => p.id === id)?.name ?? '';
  const drafts: Draft[] = [];

  for (const hire of hires) {
    const name = nameOf(hire.personId);
    if (hire.startDate > today) {
      drafts.push({
        recipientId: hire.managerId,
        createdAt: at(addDays(hire.startDate, -21)),
        type: 'hire.assigned',
        params: { person: name, date: hire.startDate },
        link: `/manager/hires/${hire.id}`,
      });
      if (hire.startDate <= addDays(today, 21)) {
        drafts.push({
          recipientId: hire.hrId,
          createdAt: at(addDays(hire.startDate, -14)),
          type: 'hire.starting',
          params: { person: name, date: hire.startDate },
          link: `/admin/hires/${hire.id}`,
        });
      }
      continue;
    }
    if (hire.status === 'completed') continue;

    let overdueCount = 0;
    let firstOverdue: string | null = null;
    for (const task of hire.tasks) {
      const status = taskStatus(task, hire.tasks, today);
      const recipientId = taskRecipient(hire, task);
      const link = taskLink(hire, task, recipientId);
      // Unblocked: a task whose dependencies were all completed recently.
      if (task.dependsOn.length && status !== 'blocked') {
        const deps = task.dependsOn.map((id) => hire.tasks.find((t) => t.id === id || t.templateTaskId === id));
        const lastDone = deps
          .map((d) => d?.completedAt)
          .filter((d): d is string => Boolean(d))
          .sort()
          .at(-1);
        if (lastDone && lastDone.slice(0, 10) >= addDays(today, -21) && task.status !== 'done') {
          drafts.push({ recipientId, createdAt: lastDone, type: 'task.unblocked', params: { task: task.title }, link });
        }
      }
      // "Por vencer" two days before the due date, also for tasks already done (history).
      const announced = addDays(task.dueDate, -DUE_SOON_DAYS);
      if (
        (task.owner === 'hire' || task.owner === 'manager') &&
        announced >= addDays(today, -SEED_HISTORY_DAYS) &&
        announced <= today &&
        (!task.completedAt || task.completedAt.slice(0, 10) >= announced)
      ) {
        drafts.push({
          recipientId,
          createdAt: at(announced),
          type: 'task.due_soon',
          params: { task: task.title, date: task.dueDate, person: name },
          link,
        });
      }
      if (task.status === 'done') continue;
      if (isPastDue(task, today)) {
        // Counted for the journey, but a blocked task is announced to whoever blocks it, not to whoever waits (F4).
        overdueCount += 1;
        if (!firstOverdue || task.dueDate < firstOverdue) firstOverdue = task.dueDate;
        if (status !== 'blocked') {
          drafts.push({
            recipientId,
            createdAt: at(addDays(task.dueDate, 1)),
            type: task.owner === 'hire' ? 'task.overdue' : 'task.journey_overdue',
            params: { task: task.title, person: name, date: task.dueDate },
            link,
          });
        }
      }
    }
    if (overdueCount > 0 && firstOverdue) {
      drafts.push({
        recipientId: hire.hrId,
        createdAt: at(addDays(firstOverdue, 1), '13:00:00'),
        type: 'journey.delayed',
        params: { person: name, count: String(overdueCount) },
        link: `/admin/hires/${hire.id}`,
      });
    }

    for (const checkin of hire.checkins) {
      const days = String(CHECKIN_OFFSETS[checkin.stage]);
      // Announced a week before the meeting, also for past check-ins (history).
      const announced = addDays(checkin.dueDate, -7);
      const soon = announced <= today && announced >= addDays(today, -SEED_HISTORY_DAYS);
      if (soon) {
        drafts.push({
          recipientId: hire.personId,
          createdAt: at(addDays(checkin.dueDate, -7)),
          type: 'checkin.self_review_pending',
          params: { days, date: checkin.dueDate },
          link: `/me/checkin/${checkin.stage}`,
        });
      }
      if (soon) {
        drafts.push({
          recipientId: hire.managerId,
          createdAt: at(addDays(checkin.dueDate, -7), '12:30:00'),
          type: 'checkin.manager_due',
          params: { person: name, days, date: checkin.dueDate },
          link: `/manager/hires/${hire.id}/checkin/${checkin.stage}`,
        });
      }
      if (checkin.hireSelfReview) {
        drafts.push({
          recipientId: hire.managerId,
          createdAt: checkin.hireSelfReview.submittedAt,
          type: 'checkin.self_review_done',
          params: { person: name, days },
          link: `/manager/hires/${hire.id}/checkin/${checkin.stage}`,
        });
      }
      if (checkin.status === 'completed' && checkin.completedAt) {
        drafts.push({
          recipientId: hire.personId,
          createdAt: checkin.completedAt,
          type: 'checkin.completed',
          params: { days },
          link: '/me',
        });
        if (checkin.action?.type === 'escalate') {
          drafts.push({
            recipientId: hire.hrId,
            createdAt: checkin.completedAt,
            type: 'checkin.escalated',
            params: { person: name, days },
            link: `/admin/hires/${hire.id}`,
          });
        }
      }
    }
  }

  const itAdmins = people.filter((p) => p.role === 'it_admin');
  for (const request of accessRequests) {
    const person = request.personId ? nameOf(request.personId) : request.email;
    for (const it of itAdmins) {
      drafts.push({
        recipientId: it.id,
        createdAt: request.createdAt,
        type: 'access_request.new',
        params: { request: request.id, person },
        link: `/it/requests/${request.id}`,
      });
    }
    if (request.resolution && request.personId) {
      drafts.push({
        recipientId: request.personId,
        createdAt: request.resolution.at,
        type: request.status === 'rejected' ? 'access_request.rejected' : 'access_request.resolved',
        params: { request: request.id },
        link: '/account/security',
      });
    }
  }
  for (const attempt of authAttempts.filter((a) => a.locked)) {
    const person = people.find((p) => p.email.toLowerCase() === attempt.email.toLowerCase());
    for (const it of itAdmins) {
      drafts.push({
        recipientId: it.id,
        createdAt: attempt.lockedAt ?? at(today),
        type: 'account.locked',
        params: { person: person?.name ?? attempt.email },
        link: '/it/security',
      });
    }
  }

  // F9: comments of the seed, with the same rule as a comment posted during the session.
  for (const comment of [...comments].sort((a, b) => a.createdAt.localeCompare(b.createdAt))) {
    const hire = hires.find((h) => h.id === comment.hireId);
    const task = hire?.tasks.find((x) => x.id === comment.hireTaskId);
    if (!hire || !task) continue;
    const earlier = comments
      .filter((c) => c.hireTaskId === comment.hireTaskId && c.createdAt < comment.createdAt)
      .map((c) => c.authorId);
    for (const n of onComment(hire, task, comment, earlier, nameOf(comment.authorId))) {
      drafts.push({ recipientId: n.recipientId, createdAt: n.createdAt, type: n.type, params: n.params, link: n.link });
    }
  }

  const readLine = addDays(today, -SEED_READ_AFTER_DAYS);
  const seen = new Map<string, number>();
  return drafts
    .filter((d) => d.createdAt.slice(0, 10) <= today)
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
    .map((d, i) => {
      const rank = seen.get(d.recipientId) ?? 0;
      seen.set(d.recipientId, rank + 1);
      const unread = rank < SEED_UNREAD_NEWEST || d.createdAt.slice(0, 10) >= readLine;
      return {
        ...makeNotification(d, `nt-seed-${String(i + 1).padStart(3, '0')}`),
        readAt: unread ? undefined : d.createdAt,
      };
    });
}

// ---------- Reading ----------

/** A person's notifications, newest first. */
export function notificationsFor(all: AppNotification[], personId: string): AppNotification[] {
  return all.filter((n) => n.recipientId === personId).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export function unreadCount(all: AppNotification[], personId: string): number {
  return all.reduce((n, item) => n + (item.recipientId === personId && !item.readAt ? 1 : 0), 0);
}

export type NotificationGroup = 'today' | 'week' | 'earlier';

/** Groups by when they arrived: today, the last 7 days and earlier. */
export function groupOf(notification: AppNotification, today = DEMO_TODAY): NotificationGroup {
  const day = notification.createdAt.slice(0, 10);
  if (day >= today) return 'today';
  if (day > addDays(today, -7)) return 'week';
  return 'earlier';
}
